CREATE TABLE "feature_switch_events" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "feature_switch_events_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"key" text NOT NULL,
	"from_enabled" boolean,
	"to_enabled" boolean NOT NULL,
	"changed_by" bigint,
	"changed_by_name" text,
	"note" text,
	CONSTRAINT "feature_switch_events_key_check" CHECK ("feature_switch_events"."key" ~ '^[a-z0-9_]{1,64}$'),
	CONSTRAINT "feature_switch_events_note_check" CHECK ("feature_switch_events"."note" IS NULL OR length("feature_switch_events"."note") <= 500)
);
